#!/bin/sh
# Generated by seaworthy: acme-agent, rpm, before removal. See seaworthy::scripts.
set -e
systemd_running() { [ -d /run/systemd/system ]; }
has_systemctl() { command -v systemctl >/dev/null 2>&1; }
try() { "$@" || echo "acme-agent: warning: '$*' failed (exit $?); continuing" >&2; }
action=none
case "${1:-}" in
  0) action=remove ;;
esac
if [ "$action" = remove ] && has_systemctl; then
  if systemd_running; then try systemctl stop AcmeAgent.service; fi
  try systemctl disable AcmeAgent.service
fi
